export function createChatOrchestrator(
  provider: AIProvider,
  promptBuilder: PromptBuilder,
  toolRegistry?: ToolRegistry,
  options?: ChatOrchestratorOptions
): ChatOrchestrator {
  const maxToolRounds = normalizeToolRounds(options?.maxToolRounds);
  const toolTimeoutMs = normalizeToolTimeout(options?.toolTimeoutMs);
  const contextConfig = createContextConfig(options?.contextConfig);
  const entryWriter = createEntryWriter(options?.entries);
  const promptBuilderOptions = options?.promptBuilderOptions;
  const hooks = options?.hooks;
  const sessionStore = options?.sessionStore;

  return {
    async processMessage(session: ChatSession): Promise<string> {
      return collectText(this.processMessageStream(session));
    },

    async *processMessageStream(session: ChatSession, options?: {signal?: AbortSignal}): AsyncGenerator<MessageChunk> {
      try {
        if (hooks?.beforeSession) await hooks.beforeSession(session);

        let userMessage = lastUserContent(session);

        if (hooks?.beforeUserInput) {
          userMessage = await rewriteUserMessage(session, userMessage, hooks.beforeUserInput);
        }

        if (hooks?.afterUserInput) await hooks.afterUserInput(session, userMessage);

        // Read every turn, never once per process, so a tool registered after construction is advertised from the next turn.
        const {baseSystemPrompt, tools} = turnTools(promptBuilder, toolRegistry, promptBuilderOptions);
        const systemPrompt = hooks?.beforeModelResponse
          ? await hooks.beforeModelResponse(session, baseSystemPrompt)
          : baseSystemPrompt;

        const messages: Message[] = toMessages(session.entries, contextConfig);
        let totalUsage: UsageMetadata | undefined;
        let responseText = '';
        const signal = options?.signal;

        // Bounded by the budget gate below, not the header: maxToolRounds executed rounds, maxToolRounds + 1 provider calls.
        for (let round = 0; ; round++) {
          log.info('orchestrator', 'starting round', {round});
          const pendingToolCalls: ToolCall[] = [];

          const outcome = yield* streamRound(provider, {messages, systemPrompt, tools, signal}, pendingToolCalls);
          // Abandoned mid-round: the provider stopped on the signal, and what it left half-done is not acted on.
          if (signal?.aborted) return;
          responseText += outcome.text;
          totalUsage = accumulateUsage(totalUsage, outcome.usage);

          if (!shouldContinueToolLoop(outcome.stopReason, pendingToolCalls, toolRegistry)) break;
          if (budgetSpent(round, maxToolRounds, pendingToolCalls)) {
            const budget = {maxToolRounds, requestedTools: pendingToolCalls.map(tc => tc.name)};
            responseText += yield* closeExhaustedTurn(session, budget, hooks?.onToolBudgetExhausted);
            break;
          }

          log.info('orchestrator', 'executing tools', {tools: pendingToolCalls.map(tc => tc.name)});
          const {clientMessages, suppressOutput} = await executeToolCalls(
            pendingToolCalls,
            messages,
            session,
            entryWriter,
            withDeadline(toolCallRunner(toolRegistry!, session, hooks?.beforeToolCall), toolTimeoutMs, signal),
            signal
          );
          // Abandoned while its tools ran: no provider call follows, so nothing they returned is read.
          if (signal?.aborted) return;
          log.info('orchestrator', 'tool execution complete', {
            clientMessageCount: clientMessages.length,
            clientMessageTypes: clientMessages.map(m => m.type),
            suppressOutput,
          });

          if (clientMessages.length > 0) {
            yield {type: 'tool_result' as const, clientMessages};
          }

          if (suppressOutput) {
            yield {type: 'suppress_output' as const};
          }
        }

        if (hooks?.afterModelResponse) await hooks.afterModelResponse(session, responseText, totalUsage);
      } catch (error) {
        // Abandoned by its caller: what the abort caused is no failure, and nobody is left to tell.
        if (options?.signal?.aborted) return;
        if (hooks?.onError) {
          await hooks.onError(
            session,
            error instanceof Error ? error : new Error(describeRejection(error), {cause: error})
          );
        }
        throw error;
      } finally {
        // Before both: a provider that threw mid-stream leaves an entry open, and nothing should persist it that way.
        entryWriter.closeTurn(session);
        try {
          if (hooks?.afterSession) await hooks.afterSession(session);
        } finally {
          await saveSession(sessionStore, session);
        }
      }
    },
  };
}

// A changed message is also written back to the session's last user entry.
async function rewriteUserMessage(
  session: ChatSession,
  userMessage: string,
  hook: (session: ChatSession, userMessage: string) => Promise<string>
): Promise<string> {
  const modified = await hook(session, userMessage);
  if (modified === userMessage) return userMessage;

  updateLastUserContent(session, modified);
  return modified;
}

// Adds per-round token counts so the hook receives the total across all provider calls in the turn.
function accumulateUsage(acc: UsageMetadata | undefined, next: UsageMetadata | undefined): UsageMetadata | undefined {
  if (!acc) return next;
  if (!next) return acc;
  return {
    inputTokens: acc.inputTokens + next.inputTokens,
    outputTokens: acc.outputTokens + next.outputTokens,
    totalTokens: acc.totalTokens + next.totalTokens,
  };
}
</document>
<document source="example/full-config.ts" type="code" relevance="0.78" tokens="1253">
const hooks: OrchestratorHooks = {
  beforeSession: async session => log.info('app', 'session opened', {sessionId: session.sessionId}),
  beforeUserInput: async (_session, userMessage) => userMessage.trim(),
  afterUserInput: async (_session, userMessage) => log.info('app', 'received', {length: userMessage.length}),
  beforeModelResponse: async (_session, systemPrompt) => systemPrompt,
  // usage is the turn's total over every tool round; inputTokens re-counts the conversation each round, as billed.
  afterModelResponse: async (_session, _responseText, usage) => log.info('app', 'answered', {usage}),
  afterSession: async session => log.info('app', 'session closed', {sessionId: session.sessionId}),
  onError: async (_session, error) => log.error('app', 'orchestration failed', {error: error.message}),
  // A human-oversight policy: a returned ToolResponse declines the call, and the model reads its result instead.
  beforeToolCall: async (_session, call: ToolCall): Promise<ToolResponse | undefined> =>
    call.name === 'send_notification'
      ? {result: 'Not performed. A human reviewer has been asked to do it.'}
      : undefined,
  // The engine writes no user-facing prose: this sentence closes a turn whose tool budget ran out.
  onToolBudgetExhausted: async () => 'I could not finish looking that up, so a colleague will follow up.',
};

const engine = createHalEngine({
  // REQUIRED: AI provider settings
  provider: {
    type: 'bedrock', // 'bedrock' | 'vertex' | 'openai' | 'anthropic' | 'mock'
    region: 'eu-west-1',
    modelId: 'eu.anthropic.claude-sonnet-4-5-20250929-v1:0',
    maxTokens: 4096, // REQUIRED for bedrock
  },

  // REQUIRED: System prompt configuration. Every field but `identity` is optional.
  prompt: {
    identity: 'You are a helpful assistant.',
    domainContext: 'You help users with weather and general questions.',
    responseGuidelines: 'Be concise. Use tools when available.',
    toolPreamble: 'Replaces the built-in instructions telling the model when to call a tool.',
  },

  // REQUIRED: Authentication. `ws` receives the upgrade request; return null to reject it.
  auth: {
    ws: async () => ({id: 'user-1'}),
    http: authMiddleware,
    // The caller headers a tool may receive as authHeaders; list only what your tools need, [] for none.
    forwardHeaders: ['authorization'],
  },

  // OPTIONAL: Tool registry
  tools: toolRegistry,

  // OPTIONAL: Session store (defaults to InMemorySessionStore)
  session: sessionStore,

  // OPTIONAL: Transport settings
  transport: {
    port: 8086, // 0 lets the OS choose; unset falls through to PORT, then 8086
    corsOrigin: ['https://example.com'],
    // basePath defaults to '/hal' and the heartbeat to 30s.
    basePath: '/hal',
    heartbeatIntervalMs: 30_000,
    // One user's inbound budget across WebSocket and HTTP, the default shown; false turns it off for a deployment whose gateway already limits.
    rateLimit: {limit: 20, windowMs: 60_000, burst: 5},
    // The connected frame's text, sent before any entry; a deployer serving EU users may carry its AI disclosure here.
    connectMessage: 'You are chatting with an AI assistant.',
    // additionalRoutes mounts under basePath and rootRoutes at /, neither gated by auth.http; errorHandler replaces Express's default HTML error page.
    additionalRoutes: router => router.get('/ping', (_req, res) => res.json({ok: true})),
    rootRoutes: router => router.get('/', (_req, res) => res.send('<h1>Hello</h1>')),
    errorHandler: (err, _req, res, _next) => res.status(500).json({error: String(err)}),
    resume: {enabled: true, latest: true}, // rejoin the conversation ?sessionId= names, else the user's latest; ?new=1 starts one; off by default, see Session Resume
    history: {enabled: true, preview: true},
  },

  // OPTIONAL: Orchestrator settings
  orchestrator: {
    maxToolRounds: 5, // Max tool rounds executed (default 5); the provider is called at most maxToolRounds + 1 times
    contextConfig: {
      // How many messages are kept, and how much of each.
      maxMessages: 50,
      maxContentLength: 4000,
    },
    entries: {
      // When a turn ends, the newest 40 entries keep their content; older ones keep only their slot, role and timestamp.
      maxContentEntries: 40,
      // Runs on every entry but a user's once its content is final; here no tool argument reaches the store.
      redactEntry: entry => (entry.role === 'tool' ? {...entry, toolInput: {}} : entry),
    },
    toolTimeoutMs: 30_000, // Abandon a tool call after this long, answering the model with a timeout result (default 30000; 0 = no deadline)
    hooks,
  },

  // OPTIONAL: Logger. Process-wide, not per engine - see docs/logging.md.
  logger: myLogger,

  // OPTIONAL: Lifecycle hooks. Fire-and-forget: never awaited, and a throw is logged and swallowed.
  onConnect: session => log.info('app', 'connected', {sessionId: session.sessionId}),
  onDisconnect: sessionId => log.info('app', 'disconnected', {sessionId}),
});
